#include "voltage_tables_view.h"
#include "voltage_offsets_profile.h"
#include "profile_catalog.h"
#include <imgui_internal.h>
#include <cstdio>
#include <cstring>
using namespace druta::ui;
namespace {
unsigned checks=0;void check(bool yes,const char* message){++checks;if(!yes){std::fprintf(stderr,"Offset UI: %s\n",message);std::abort();}}
std::vector<VoltageTablesIntent> frame(VoltageTablesViewState& state,VoltageTablesData& data,bool unlocked=true,bool classic=false){ImGui::GetIO().DisplaySize={1800,1400};ImGui::NewFrame();ImGui::SetNextWindowSize({1750,1350});ImGui::Begin("Installed offset UI test");auto* w=ImGui::GetCurrentWindow();const auto scope=ImHashStr("voltage-tables",0,w->ID);w->StateStorage.SetInt(ImHashStr("Policy scaffold offsets",0,scope),1);auto out=draw_voltage_tables_controls(state,&data,7,false,unlocked,classic);ImGui::End();ImGui::Render();return out;}
std::vector<VoltageTablesIntent> press(VoltageTablesViewState& state,VoltageTablesData& data,const char* label,bool unlocked=true,bool row=false,bool offsets=true){auto* w=ImGui::FindWindowByName("Installed offset UI test");auto id=ImHashStr("voltage-tables",0,w->ID);if(offsets)id=ImHashStr("installed-offsets",0,id);if(row){id=ImHashStr("offset-fields",0,id);int rail=0,field=0;id=ImHashData(&rail,sizeof(rail),id);id=ImHashData(&field,sizeof(field),id);}ImGui::ActivateItemByID(ImHashStr(label,0,id));return frame(state,data,unlocked);}
void run(){VoltageTablesData data;data.identity.size=sizeof(data.identity);std::strcpy(data.identity.slot,"0000:05:00.0");std::strcpy(data.identity.uuid,"GPU-installed-offset-view");data.offsets_recognized=true;data.gate_enabled=false;
 VoltageTableRow row;row.key={VoltageTableFamily::offsets,0,0};row.label="NVVDD REL offset";row.binding="fresh-owned-head";row.value=-10000;row.initial=0;row.reported=900000;row.availability=VoltagePolicyAvailability::available;row.writable=true;data.rows={row};VoltageTablesViewState state;check(frame(state,data).empty(),"Rendering issues no request");check(state.drafts.size()==1&&std::strcmp(state.drafts[0].text.data(),"-10.000")==0,"Signed offset initializes exact mV draft");std::strcpy(state.drafts[0].text.data(),"-25.000");state.drafts[0].dirty=true;
 auto out=press(state,data,"Apply",true,true);check(out.size()==1&&out[0].families==2&&out[0].requests[0].key.family==VoltageTableFamily::offsets&&out[0].requests[0].value==-25000&&out[0].requests[0].expected==-10000&&out[0].requests[0].binding==row.binding,"Offset Apply routes family2 with immutable expected/binding");out=press(state,data,"Restore initial",true,true);check(out.size()==1&&out[0].families==2&&out[0].operation==VoltageTablesIntent::Operation::restore_initial,"Initial restoration routes selected offset only");check(press(state,data,"Apply",false,true).empty(),"Locked controls refuse new offset request");data.rows[0].stale=true;check(press(state,data,"Apply",true,true).empty(),"Stale installed request cannot Apply");data.rows[0].stale=false;
 data.offset_recovery_pending=true;check(press(state,data,"Apply",true,true).empty(),"Uncertain offset blocks new edit");out=press(state,data,"Recover installed offsets",false);check(out.size()==1&&out[0].families==2&&out[0].operation==VoltageTablesIntent::Operation::recover,"Offset recovery remains reachable while locked");data.offset_recovery_pending=false;data.offset_undo_available=true;out=press(state,data,"Undo installed offsets",false);check(out.size()==1&&out[0].families==2&&out[0].operation==VoltageTablesIntent::Operation::undo,"Offset Undo has independent flags/family");
 state.drafts[0].include=true;out=press(state,data,"Save selected offsets profile");check(out.size()==1&&out[0].families==2&&out[0].selection.size()==1,"Selected offsets save distinct manual profile");check(press(state,data,"Save selected requests profile",true,false,false).empty(),"Offset include cannot leak into ordinary requests Save");out=press(state,data,"Load offsets profile");check(out.size()==1&&out[0].families==2&&out[0].operation==VoltageTablesIntent::Operation::load_profile,"Offset Load intent selects current family");
 auto document=capture_voltage_offsets_profile(data,{row.key});document["fields"][0]["value_uv"]=-30000;data.rows[0].writable=false;check(stage_voltage_tables_document(state,document,data)&&state.offsets_staged.size()==1&&state.staged.empty(),"Gate-off load stages offset draft separately");check(press(state,data,"Apply staged offsets").empty(),"Unqualified writer cannot Apply staged offsets");data.rows[0].writable=true;out=press(state,data,"Apply staged offsets");check(out.size()==1&&out[0].families==2&&out[0].requests[0].value==-30000,"Staged offsets require explicit family2 Apply");
 const auto description=inspect_profile(document);check(description.valid&&description.scope==ProfileScope::voltage_tables&&description.targets==std::vector<std::string>({"voltage:scaffold-offset:0:0"}),"Catalog detects native installed-offset target");ProfileJson python={{"schema",2},{"scope","voltage_offsets"},{"voltage_offsets",{{"slot",data.identity.slot},{"values",{{"voltage.0.REL.offset",-30000},{"voltage.1.OV.offset",0}}}}}};check(inspect_profile(python).valid&&inspect_profile(python).targets.size()==2,"Catalog detects released Python offset schema");const auto subset=select_profile_targets(python,{"voltage:scaffold-offset:1:2"});check(subset["voltage_offsets"]["values"].size()==1&&inspect_profile(subset).valid,"Catalog uses typed offset subsetter");auto invalid=python;invalid["voltage_offsets"]["values"]["voltage.0.REL.offset"]=true;check(!inspect_profile(invalid).valid,"Catalog rejects malformed offset source before selection");
 frame(state,data,true,true);check(state.offsets_staged.size()==1,"Both skins share staged offsets");sync_voltage_tables_view(state,&data,8);check(state.offsets_staged.empty()&&state.staged.empty()&&!state.drafts[0].dirty,"Adapter generation retires old offset drafts and plans");}
}
int main(){ImGui::CreateContext();auto& io=ImGui::GetIO();io.IniFilename=nullptr;io.DeltaTime=1.f/60;unsigned char* pixels=nullptr;int width=0,height=0;io.Fonts->GetTexDataAsRGBA32(&pixels,&width,&height);run();ImGui::DestroyContext();std::printf("Voltage offset view/catalog: %u checks\n",checks);return 0;}
